fn prepare_writes(a: &Attempt, dir: &Path, env: &mut Vec<(String, String)>) -> Result<()> {
    // New per attempt, so nothing in it is an earlier run's.
    if let Some(ev) = &a.evidence {
        env.push((
            format!("DISPATCH_WRITES_{}", env_key(&ev.name)),
            ev.dir.display().to_string(),
        ));
    }
    for (name, path) in a.artifacts.iter().filter(|(n, _)| *n != "checks") {
        env.push((
            format!("DISPATCH_WRITES_{}", env_key(name)),
            path.display().to_string(),
        ));
        match std::fs::remove_file(path) {
            Err(e) if e.kind() != std::io::ErrorKind::NotFound => {
                return Err(e).with_context(|| format!("removing {name}"));
            }
            _ => {}
        }
    }

    /// `input_where` for a reader who wants the document as it stands: a
    /// workflow attempt still open counts too, since a review edits its
    /// copy in place until `finalize` is answered. Display only; an agent
    /// is handed `input_where`'s complete files.
    #[must_use]
    pub fn shown_where(
        &self,
        name: &str,
        keep: impl Fn(&Attempt) -> bool,
    ) -> Option<(&Attempt, &PathBuf)> {
        self.attempts
            .iter()
            .rev()
            .filter(|a| !a.forgotten.contains_key(name))
            .filter(|a| {
                a.state == AttemptState::Complete
                    || (a.kind == AttemptKind::Workflow && a.is_open())
            })
            .filter(|a| keep(a))
            .find_map(|a| a.artifacts.get(name).map(|p| (a, p)))
    }

